    if (!o.sh) continue;
    for (let y = o.y[0]; y <= o.y[1]; y++) {
      if (o.face === "north" || o.face === "south") {
        g.set(o.x[0] - 1, y, o.z[0], SHUTTER);
        g.set(o.x[1] + 1, y, o.z[0], SHUTTER);
      } else {
        g.set(o.x[0], y, o.z[0] - 1, SHUTTER);
        g.set(o.x[0], y, o.z[1] + 1, SHUTTER);
